export interface IStorageProvider {
  /**
   * Upload a buffer to object storage.
   * @param key Opaque object key (already generated by caller)
   * @param body Buffer of file data
   * @param contentType MIME type string
   * @param metadata Optional user‑defined metadata (e.g. original filename)
   * @throws StorageError on failure
   */
  upload(key: string, body: Buffer, contentType: string, metadata?: Record<string, string>): Promise<void>;

  /**
   * Generate a short‑lived signed URL for downloading the object.
   * @param key Object key to download
   * @param expiresInSeconds Expiration in seconds (e.g. 900 for 15 min)
   */
  getSignedDownloadUrl(key: string, expiresInSeconds?: number): Promise<string>;

  /**
   * Delete an object permanently.
   */
  deleteObject(key: string): Promise<void>;

  /**
   * Get an object buffer from storage.
   */
  getBuffer?(key: string): Promise<Buffer>;

  /**
   * Perform a lightweight health check (e.g. list bucket or head bucket).
   */
  checkHealth(): Promise<void>;
}

export class StorageError extends Error {
  constructor(message: string) {
    super(message);
    this.name = 'StorageError';
  }
}

